import sys

def main():
    n = int(sys.stdin.read().strip())
    result = []
    for i in range(n):
        row = []
        for j in range(n):
            if (i + j) % 2 == 0:
                row.append('W')
            else:
                row.append('B')
        result.append(''.join(row))
    for line in result:
        print(line)

main()
